using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Runtime.Serialization;
using System.Threading;
using System.Windows.Forms;

namespace AgitCon {
    [DataContract] sealed class QualityFixture {[DataMember]public string Id,Path,Expected;}
    [DataContract] sealed class QualityCase {[DataMember]public string Query,Intent;[DataMember]public List<ReactionScore> Ranking;[DataMember]public List<Entry> Results;[DataMember]public bool RelatedSmile;}
    [DataContract] sealed class OcrAuditItem {[DataMember]public string Id;[DataMember]public OcrText Result;}
    static class QualityAudit {
        public static void SmileScopes(bool allEmotions=false){Application.EnableVisualStyles();SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());var context=new ApplicationContext();var timer=new System.Windows.Forms.Timer{Interval=1};timer.Tick+=async(s,e)=>{timer.Stop();try{
            using(var search=new SemanticSearch(()=>new GemmaHost(Path.Combine(SemanticSearch.Root,"gemma2","smile-audit-profile")),()=>SemanticSearch.Ready,Path.Combine(SemanticSearch.Root,"vectors",SemanticSearch.Spec))){search.AutomaticAnalysis=true;var entries=Catalog.Load().Entries.Where(x=>!String.IsNullOrEmpty(x.Path)&&File.Exists(x.Path)).ToList();var scopes=new Dictionary<string,List<Entry>>{{"all",entries}};foreach(var group in entries.GroupBy(x=>x.PackId??"local"))scopes[group.Key]=group.ToList();var cases=new List<QualityCase>();
                foreach(var scope in scopes)foreach(string query in (allEmotions?new[]{"ㅋㅋㅋ","굳","너무 슬퍼","사랑해","걱정돼","화나","졸려","미안해요","안녕","깜짝이야","고마워요","행복해","감기 걸렸어","배고파","부끄러워","안 웃겨"}:new[]{"ㅋ","ㅋㅋㅋ","ㅋㅋㅋㅋ","ㅎㅎㅎ"})){var found=await search.Search(query,scope.Value,CancellationToken.None);cases.Add(new QualityCase{Query=scope.Key+" / "+query,Intent=RecommendationQuery.Intent(query).Key,Results=found,Ranking=allEmotions?search.LastRanking.ToList():null,RelatedSmile=search.UsedSmileFallback});}
                File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,(allEmotions?"quality-emotion-scopes.json":"quality-smile-scopes.json")),GemmaHost.Json(cases));File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,(allEmotions?"quality-emotion-scopes.txt":"quality-smile-scopes.txt")),"PASS: "+cases.Count+" fixed reaction queries across full catalog and individual packs. External requests="+search.BlockedRequests+". No draft reading or KakaoTalk interaction.");
            }
        }catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,(allEmotions?"quality-emotion-scopes.txt":"quality-smile-scopes.txt")),"FAIL: "+ex);Environment.ExitCode=1;}finally{timer.Dispose();context.ExitThread();}};timer.Start();Application.Run(context);}
        public static void Ocr(){Application.EnableVisualStyles();SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());var context=new ApplicationContext();var timer=new System.Windows.Forms.Timer{Interval=1};timer.Tick+=async(s,e)=>{timer.Stop();string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-ocr.txt");try{using(var host=new GemmaHost(Path.Combine(SemanticSearch.Root,"gemma2","ocr-audit-profile"),"ocr-audit.html")){host.Diagnostics=stage=>File.WriteAllText(report,"RUNNING: "+stage);await host.Start(CancellationToken.None);var fixtures=GemmaHost.Read<List<QualityFixture>>(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"benchmark-fixtures.json")));var results=new List<OcrAuditItem>();foreach(var fixture in fixtures)results.Add(new OcrAuditItem{Id=fixture.Id,Result=await host.ReadText(fixture.Path,CancellationToken.None)});File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-ocr.json"),GemmaHost.Json(results));File.WriteAllText(report,"PASS: "+results.Count+" isolated sticker images. External requests="+host.BlockedRequests+". No model/GPU or KakaoTalk interaction.");}}catch(Exception ex){File.WriteAllText(report,"FAIL: "+ex);Environment.ExitCode=1;}finally{timer.Dispose();context.ExitThread();}};timer.Start();Application.Run(context);}

        public static void Run(string label){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());var context=new ApplicationContext();var timer=new System.Windows.Forms.Timer{Interval=1};timer.Tick+=async(s,e)=>{timer.Stop();try{using(var search=new SemanticSearch(()=>new GemmaHost(Path.Combine(SemanticSearch.Root,"gemma2","audit-profile")),()=>SemanticSearch.Ready,label=="independent"?Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-work","independent-"+Guid.NewGuid().ToString("N")):Path.Combine(SemanticSearch.Root,"vectors",SemanticSearch.Spec))){var entries=Catalog.Load().Entries.Where(item=>!String.IsNullOrEmpty(item.Path)&&File.Exists(item.Path)).ToList();if(label=="laugh-library")entries=GemmaHost.Read<List<Entry>>(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-full-library.json")));if(label=="full-library"){
                    entries=Catalog.Load().Entries.Select(item=>new Entry{Path=item.Path,OriginalPath=item.OriginalPath,SourceUrl=item.SourceUrl,PackId=item.PackId,DisplayName=item.DisplayName,Aliases=item.Aliases,RemoteId=item.RemoteId,Format=item.Format}).ToList();
                    int completed=0,failed=0;var available=new List<Entry>();
                    foreach(var entry in entries){try{await search.PrepareRemote(entry,CancellationToken.None);available.Add(entry);completed++;}catch(Exception){failed++;}File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-full-library-progress.txt"),"Prepared="+completed+"; failed="+failed+"; total="+entries.Count);}
                    File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-full-library.json"),GemmaHost.Json(available));File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-full-library.txt"),"Prepared="+completed+"; failed="+failed+"; total="+entries.Count+". Catalog not modified. Public sticker images only; no KakaoTalk interaction.");return;
                }if(label=="training"){
                    var fixtures=GemmaHost.Read<List<QualityFixture>>(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tuning-training.json")));
                    foreach(var fixture in fixtures)await search.Index(new Entry{Path=fixture.Path},CancellationToken.None);
                    File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-training.txt"),"PASS: "+fixtures.Count+" isolated reference images encoded. Catalog unchanged. External requests="+search.BlockedRequests);return;
                }if(label=="benchmark"||label=="benchmark-full"||label=="independent"||label=="catalog-only"||label=="caption-baseline"||label=="caption-enabled"||label=="catalog-analyzed"||label.StartsWith("error-holdout-")){
                    if(label=="benchmark-full"||label=="catalog-only"||label=="catalog-analyzed")entries=GemmaHost.Read<List<Entry>>(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-full-library.json")));
                    var fixtures=(label=="catalog-only"||label=="catalog-analyzed")?new List<QualityFixture>():GemmaHost.Read<List<QualityFixture>>(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,(label.StartsWith("error-holdout-")?"error-holdout-fixtures.json":label.StartsWith("caption-")?"caption-fixtures.json":label=="independent"?"independent-fixtures.json":"benchmark-fixtures.json"))));
                    if(label=="independent"||label.StartsWith("caption-")||label.StartsWith("error-holdout-"))entries.Clear();search.AutomaticAnalysis=label=="caption-enabled"||label=="catalog-analyzed"||label.StartsWith("error-holdout-");
                    entries.AddRange(fixtures.Select(f=>new Entry{Path=f.Path,DisplayName=f.Id,PackId="test"}));
                    var cases=new List<QualityCase>();
                    foreach(string testQuery in new[]{"ㅋㅋㅋ","진짜 웃기네ㅋㅋ","굳","너무 좋아요","ㅠㅠ","너무 슬퍼","사랑해","당황했어","화나","졸려","미안해요","안녕","깜짝이야","고마워요","안 웃겨","굳이 그럴 필요 없어","고양이가 인사하는 모습","배고파","감기 걸렸어","행복해","부끄러워","ㅎㅇ","ㅇㅋ","ㅋㅋㅠㅠ"}){
                        var result=await search.Search(testQuery,entries,CancellationToken.None);var reaction=RecommendationQuery.Intent(testQuery);
                        cases.Add(new QualityCase{Query=testQuery,Intent=reaction==null?"free":reaction.Key,Results=result,Ranking=search.LastRanking.ToList(),RelatedSmile=search.UsedSmileFallback});
                    }
                    File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-"+label+".json"),GemmaHost.Json(cases));File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-reaction-vectors.json"),GemmaHost.Json(search.reactionVectors));
                    File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-"+label+".txt"),"PASS: "+cases.Count+" fixed test phrases, "+entries.Count+" candidates including "+fixtures.Count+" isolated visual controls. Model starts="+search.ModelInitializations+". External requests="+search.BlockedRequests+". Catalog unchanged; no KakaoTalk interaction.");return;
                }if(label=="laugh-control")entries.Add(new Entry{Path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-work","laugh-control.gif"),DisplayName="900063",PackId="test"});var found=await search.Search(label.Contains("laugh")?"ㅋㅋㅋ":"굳",entries,CancellationToken.None);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-"+label+".json"),GemmaHost.Json(found.ToArray()));File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-"+label+"-scores.json"),GemmaHost.Json(search.LastRanking));MainForm.RenderRankedSample(found,"quality-"+label+".png",null);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-"+label+".txt"),"Query: fixed test expression. Cached candidates="+entries.Count+"; results="+found.Count+"; external requests="+search.BlockedRequests+". No KakaoTalk interaction.\r\n");}}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-"+label+".txt"),"FAIL: "+ex);Environment.ExitCode=1;}finally{timer.Dispose();context.ExitThread();}};timer.Start();Application.Run(context);}
    }
}
